#include <stdio.h>
#include <string.h>
#include <stdlib.h>
int is_pal(const char *s) {
    int l = 0, r = strlen(s) - 1;
    while (l < r) if (s[l++] != s[r--]) return 0;
    return 1;
}
int main() {
    long long val; int limit = 50;
    if (scanf("%lld %d", &val, &limit) < 1) return 0;
    int is_lychrel = 1;
    for (int i = 0; i < limit; i++) {
        long long r = 0, tmp = val;
        while (tmp > 0) { r = r * 10 + (tmp % 10); tmp /= 10; }
        val += r;
        char buf[50]; sprintf(buf, "%lld", val);
        if (is_pal(buf)) { is_lychrel = 0; break; }
    }
    printf("%s\n", is_lychrel ? "Yes" : "No");
    return 0;
}

