    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            BigInteger val = new BigInteger(sc.next());
            int limit = sc.hasNextInt() ? sc.nextInt() : 50;
            boolean isLychrel = true;
            for (int i = 0; i < limit; i++) {
                String s = val.toString();
                BigInteger rev = new BigInteger(new StringBuilder(s).reverse().toString());
                val = val.add(rev);
                String nextS = val.toString();
                if (nextS.equals(new StringBuilder(nextS).reverse().toString())) {
                    isLychrel = false;
                    break;
                }
            }
            System.out.println(isLychrel ? "Yes" : "No");
        }
    }
}

